import * as THREE from 'three/webgpu';
import { attribute, color, mix, step, float } from 'three/tsl';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { BODY_SPECS, CAR_PARTS, buildCarGeometry, buildCarProxyGeometry, createLoftedCarMaterial } from './actor-models.js';
import { blockAt, ISLAND_BOUNDS } from './city-config.js';
import { createContactShadowMaterial } from './tsl-materials.js';

// València's parked cars and motorbikes, generated by tools/build-parking.py from the Ajuntament's on-street bay
// markings (Aparcaments no regulats, ORA), kerb lines, motorbike bays and taxi ranks, with the waste and glass
// containers' places left free (Ajuntament de València, CC BY 4.0). VLP1 (gzipped): magic, u32 count, then columns:
// x, z as u16 deltas (0.1 m from -1500 / -1700, mod 65536), yaw as u16 deltas (65536ths of a turn), kind u8
// (KINDS below), paint u8 (PAINT), kerb u8 (which way the kerb lies in the vehicle's frame: 0 unknown, 1 +x, 2 -x,
// 3 +z (ahead), 4 -z (behind)).
//
// Static: the vehicles never move. Near the camera they are the full lofted models (actor-models.js, the traffic's
// own, plus a hatchback and a small van derived from them), further out the ~250-triangle stand-ins, beyond FAR none;
// the instance lists are refilled from a coarse grid whenever the camera has moved a few metres. Each car is an
// oriented box in the player's static colliders.

const response = await fetch(new URL('./vlc-parked.bin.gz', import.meta.url));
if (!response.ok) throw new Error(`Parked vehicle data request failed: ${response.status}`);
const body = new Uint8Array(await response.arrayBuffer());
const data = body[0] === 0x1f && body[1] === 0x8b
  ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
  : body;
if (String.fromCharCode(...data.subarray(0, 4)) !== 'VLP1') throw new Error('Invalid parked vehicle data.');

const KINDS = ['hatch', 'sedan', 'suv', 'van', 'taxi', 'moto'];
// length, half width (as tools/build-parking.py)
const SIZE = { hatch: [4.0, 0.86], sedan: [4.5, 0.93], suv: [4.6, 0.97], van: [4.4, 0.92], taxi: [4.5, 0.93], moto: [2.05, 0.4] };
// The Spanish fleet's colours: whites, silvers and greys first
const PAINT = [0xf0f1f0, 0xe4e6e3, 0xbfc4c8, 0x9da2a6, 0x55595e, 0x17191c, 0x1f3354, 0x3f6aa0, 0xa3171c, 0x5e1a1e, 0xc9bda3, 0x5f665c,
  0x8a4b22, 0xd8b23a].map((h) => new THREE.Color(h));

function decode(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const n = view.getUint32(4, true);
  const o = 8;
  const out = { n, x: new Float32Array(n), z: new Float32Array(n), yaw: new Float32Array(n), kind: new Uint8Array(n), paint: new Uint8Array(n), kerb: new Uint8Array(n) };
  let X = 0, Z = 0, Y = 0;
  for (let i = 0; i < n; i++) {
    X = (X + view.getUint16(o + i * 2, true)) & 0xffff;
    Z = (Z + view.getUint16(o + n * 2 + i * 2, true)) & 0xffff;
    Y = (Y + view.getUint16(o + n * 4 + i * 2, true)) & 0xffff;
    out.x[i] = X / 10 - 1500;
    out.z[i] = Z / 10 - 1700;
    out.yaw[i] = (Y / 65536) * Math.PI * 2;
  }
  out.kind.set(bytes.subarray(o + n * 6, o + n * 7));
  out.paint.set(bytes.subarray(o + n * 7, o + n * 8));
  out.kerb.set(bytes.subarray(o + n * 8, o + n * 9));
  return out;
}

export const PARKED = decode(data);

// ---------------------------------------------------------------------------------------------------------------------
// Body specs: the traffic's saloon, SUV and taxi, plus a small hatchback (the saloon at 4.0 m with a hatch tail) and a
// small van (the SUV at 4.4 m with a tall, long roof)

function scaledSpec(src, name, k, edit) {
  const s = structuredClone({ ...src, _layout: undefined });
  delete s._layout;
  s.name = name;
  const zs = (pairs) => pairs.map(([z, v]) => [z * k, v]);
  s.zFront *= k; s.zRear *= k; s.wheelZ *= k;
  for (const key of ['halfWidth', 'sill', 'shoulder', 'edge', 'crown', 'tumble']) s[key] = zs(s[key]);
  for (const end of ['nose', 'tail']) for (const key of Object.keys(s[end])) s[end][key] = [s[end][key][0] * k, ...s[end][key].slice(1)];
  const c = s.cabin;
  c.cowl *= k; c.roofFront *= k; c.roofRear *= k; c.deck *= k;
  c.roofY = zs(c.roofY);
  c.pillars = c.pillars.map((z) => z * k);
  s.doors = s.doors.map((z) => z * k);
  s.handles = s.handles.map((z) => z * k);
  edit(s);
  s.lamps = [s.headlight[1], s.taillight[1]];
  s.lampX = [s.headlight[0], s.taillight[0]];
  return s;
}

const SPECS = {
  sedan: BODY_SPECS.sedan,
  suv: BODY_SPECS.suv,
  taxi: BODY_SPECS.taxi,
  hatch: scaledSpec(BODY_SPECS.sedan, 'parked_hatch', 0.89, (s) => {
    // the roof runs on to a near-upright tailgate
    s.cabin.roofRear = -1.42;
    s.cabin.deck = -1.82;
    s.cabin.roofY = [[0.0, 1.46], [-0.7, 1.47], [-1.42, 1.43]];
    s.cabin.pillars = [-0.3, -1.1];
    s.doors = [0.75, -0.3, -0.95];
    s.handles = [-0.13, -0.8];
    s.shoulder = [[2.0, 0.66], [0, 0.71], [-2.0, 0.79]];
    s.edge = s.edge.map(([z, v]) => [z, z < -1.2 ? Math.max(v, 0.95) : v]);
    s.chrome = false;
    s.rearWiper = true;
  }),
  van: scaledSpec(BODY_SPECS.suv, 'parked_van', 0.957, (s) => {
    s.cabin.roofFront = 0.25;
    s.cabin.roofRear = -1.98;
    s.cabin.deck = -2.08;
    s.cabin.cowl = 0.95;
    s.cabin.roofY = [[0.25, 1.86], [-0.9, 1.9], [-1.98, 1.9]];
    s.cabin.pillars = [-0.25, -1.15];
    s.rails = false;
    s.cladding = 0.42;
  })
};

// A motorbike / maxi-scooter: wheels, fairing in the paint colour, dark seat and bars (partId 0 paint, 1 dark, 2 metal)
function buildMotoGeometry(detail) {
  const parts = [];
  const add = (geo, id) => {
    const g = geo.index ? geo.toNonIndexed() : geo;
    g.deleteAttribute('uv');
    g.setAttribute('partId', new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count).fill(id), 1));
    parts.push(g);
  };
  const seg = detail ? 16 : 7;
  for (const [z, r] of [[0.66, 0.27], [-0.68, 0.28]]) {
    add(new THREE.TorusGeometry(r - 0.06, 0.06, detail ? 6 : 3, seg).rotateY(Math.PI / 2).translate(0, r, z), 1); // tyre
    if (detail) add(new THREE.CylinderGeometry(r - 0.1, r - 0.1, 0.06, 10).rotateZ(Math.PI / 2).translate(0, r, z), 2); // rim
  }
  // maxi-scooter: rounded rear body under the seat, a step-through floor, the front shield and its mudguard
  add(new THREE.CapsuleGeometry(0.19, 0.62, 3, detail ? 10 : 5).rotateX(Math.PI / 2 - 0.12).scale(1, 1.15, 1).translate(0, 0.6, -0.36), 0);
  add(new THREE.CapsuleGeometry(0.15, 0.62, 2, detail ? 8 : 4).rotateX(Math.PI / 2 - 0.1).scale(1, 0.55, 1).translate(0, 0.84, -0.3), 1); // seat
  add(new THREE.BoxGeometry(0.3, 0.1, 0.62).translate(0, 0.36, 0.18), 0); // floor
  add(new THREE.CapsuleGeometry(0.17, 0.42, 2, detail ? 8 : 4).scale(1.15, 1, 0.6).rotateX(-0.32).translate(0, 0.78, 0.5), 0); // shield
  add(new THREE.BoxGeometry(0.14, 0.08, 0.5).rotateX(0.35).translate(0, 0.55, 0.72), 0); // mudguard
  add(new THREE.CylinderGeometry(0.025, 0.025, 0.62, 5).rotateX(-0.42).translate(0, 0.56, 0.6), 2); // fork
  add(new THREE.CylinderGeometry(0.018, 0.018, 0.66, 5).rotateZ(Math.PI / 2).translate(0, 1.08, 0.6), 1); // handlebar
  if (detail) {
    add(new THREE.BoxGeometry(0.34, 0.26, 0.02).rotateX(-0.5).translate(0, 1.2, 0.66), 1); // screen
    add(new THREE.BoxGeometry(0.34, 0.26, 0.36).translate(0, 1.0, -0.78), 1); // top box
    for (const s of [-1, 1]) add(new THREE.BoxGeometry(0.02, 0.08, 0.14).translate(s * 0.38, 1.16, 0.56), 1); // mirrors
  }
  return mergeGeometries(parts);
}

function createMotoMaterial() {
  const mat = new THREE.MeshStandardNodeMaterial({ roughness: 0.45, metalness: 0.1 });
  const id = attribute('partId', 'float');
  const paint = attribute('paintColor', 'vec3');
  const dark = color(0x141517);
  const metal = color(0x8a8d90);
  mat.colorNode = mix(mix(paint, dark, step(0.5, id)), metal, step(1.5, id));
  mat.roughnessNode = mix(float(0.4), float(0.75), step(0.5, id));
  return mat;
}

// ---------------------------------------------------------------------------------------------------------------------

const DEBUG = typeof location !== 'undefined' && new URLSearchParams(location.search).has('debug') ? [] : null;
if (DEBUG) globalThis.__parkedDrops = DEBUG;

const NEAR = 120; // full models within this distance of the camera
const FAR = 520; // stand-ins out to here (a car is ~3 px tall at 500 m)
const SHADOW = 220; // contact shadows out to here
const CELL = 64;
const MOVE = 6; // refill the lists when the camera has moved this far

/**
 * Builds the parked vehicles into the scene. `network` (traffic.js) keeps cars off the game's moving lanes; returns
 * { group, colliders (oriented boxes for the player's static colliders), update(cameraPosition), stats }.
 */
export function buildParkedVehicles(scene, { network = null } = {}) {
  const P = PARKED;
  const n = P.n;
  const group = new THREE.Group();
  group.name = 'ParkedVehicles';
  scene.add(group);

  // 1. Fit each vehicle to the game's own street: off the raised sidewalks (moving it away from the kerb, as the game's
  //    kerbs are not all where the real ones are) and out of the moving traffic's lanes
  const lanes = laneIndex(network);
  const junctions = junctionIndex(network);
  const keep = new Uint8Array(n);
  const X = new Float32Array(n), Z = new Float32Array(n), Y = new Float32Array(n);
  const stats = { data: n, kept: 0, shifted: 0, onPavement: 0, droppedJunction: 0, droppedSidewalk: 0, droppedLane: 0 };
  const kindIndex = P.kind;
  for (let i = 0; i < n; i++) {
    const kind = KINDS[kindIndex[i]];
    const [L, hw] = SIZE[kind];
    const yaw = P.yaw[i];
    const cs = Math.cos(yaw), sn = Math.sin(yaw);
    // car frame: +x -> (cs, -sn), +z -> (sn, cs)
    let ox = 0, oz = 0;
    const k = P.kerb[i];
    if (k === 1) { ox = -cs; oz = sn; } else if (k === 2) { ox = cs; oz = -sn; } else if (k === 3) { ox = -sn; oz = -cs; } else if (k === 4) { ox = sn; oz = cs; }
    let x = P.x[i], z = P.z[i];
    let ok = clearOfSidewalk(x, z, cs, sn, L, hw);
    const maxShift = kind === 'moto' ? 1.2 : 5.6;
    for (let s = 0.2; !ok && (ox || oz) && s <= maxShift + 1e-6; s += 0.2) {
      ok = clearOfSidewalk(P.x[i] + ox * s, P.z[i] + oz * s, cs, sn, L, hw);
      if (ok) { x = P.x[i] + ox * s; z = P.z[i] + oz * s; stats.shifted++; }
    }
    let y = 0;
    if (!ok && kind === 'moto') {
      // a motorbike bay where the game's sidewalk is wider than the real one: the bikes stand on the pavement there
      // (as many do in València), wholly on it, at its height
      for (let s = 0; !ok && s <= 2.0 + 1e-6; s += 0.25) {
        const tx = P.x[i] - ox * s, tz = P.z[i] - oz * s;
        if (onOneBlock(tx, tz, cs, sn, L, hw)) {
          const b = blockAt(tx, tz);
          ok = true; x = tx; z = tz;
          y = b.park > 0.6 && !b.median && b.area > 250 ? ISLAND_BOUNDS.parkPavingHeight : ISLAND_BOUNDS.sidewalkHeight;
          stats.onPavement++;
        }
      }
    }
    if (!ok) { stats.droppedSidewalk++; if (DEBUG) DEBUG.push([i, 's', x, z]); continue; }
    if (junctions && kind !== 'moto' && inJunction(junctions, x, z)) { stats.droppedJunction++; if (DEBUG) DEBUG.push([i, 'j', x, z]); continue; }
    if (lanes && kind !== 'moto' && inLane(lanes, x, z, cs, sn, L, hw)) { stats.droppedLane++; if (DEBUG) DEBUG.push([i, 'l', x, z]); continue; }
    keep[i] = 1;
    X[i] = x; Z[i] = z; Y[i] = y;
  }

  // 2. Per-vehicle matrices, the grid and the colliders
  const ids = [];
  for (let i = 0; i < n; i++) if (keep[i]) ids.push(i);
  stats.kept = ids.length;
  const mats = new Float32Array(ids.length * 16);
  const shadowMats = new Float32Array(ids.length * 16);
  const paints = new Float32Array(ids.length * 3);
  const kinds = new Uint8Array(ids.length);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), up = new THREE.Vector3(0, 1, 0), v = new THREE.Vector3(), sc = new THREE.Vector3();
  const grid = new Map();
  const colliders = [];
  ids.forEach((i, j) => {
    const kind = KINDS[kindIndex[i]];
    const [L, hw] = SIZE[kind];
    q.setFromAxisAngle(up, P.yaw[i]);
    m.compose(v.set(X[i], Y[i], Z[i]), q, sc.set(1, 1, 1)).toArray(mats, j * 16);
    m.compose(v.set(X[i], Y[i] + 0.02, Z[i]), q, sc.set(hw * 2.25, 1, L * 1.06)).toArray(shadowMats, j * 16);
    const c = PAINT[P.paint[i]] || PAINT[0];
    paints.set([c.r, c.g, c.b], j * 3);
    kinds[j] = kindIndex[i];
    const key = Math.floor(X[i] / CELL) * 100000 + Math.floor(Z[i] / CELL);
    let list = grid.get(key);
    if (!list) grid.set(key, (list = []));
    list.push(j);
    const cs = Math.cos(P.yaw[i]), sn = Math.sin(P.yaw[i]);
    const ex = Math.abs(cs) * hw + Math.abs(sn) * L / 2, ez = Math.abs(sn) * hw + Math.abs(cs) * L / 2;
    colliders.push({ minX: X[i] - ex, maxX: X[i] + ex, minZ: Z[i] - ez, maxZ: Z[i] + ez, minY: Y[i], maxY: Y[i] + (kind === 'moto' ? 1.2 : 1.5), parked: true,
      obb: { cx: X[i], cz: Z[i], hx: hw, hz: L / 2, cs, sn } });
  });

  // 3. Instanced meshes: per kind a near and a far one, sized for the most of that kind the lists can hold
  const flat = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
  const shadowMesh = new THREE.InstancedMesh(flat, createContactShadowMaterial(), 4096);
  shadowMesh.name = 'ParkedShadows';
  shadowMesh.renderOrder = 1;
  const meshes = KINDS.map((kind) => {
    const moto = kind === 'moto';
    const mk = (geo, mat, cap, lod) => {
      geo.setAttribute('paintColor', new THREE.InstancedBufferAttribute(new Float32Array(cap * 3), 3));
      if (!moto) geo.setAttribute('carState', new THREE.InstancedBufferAttribute(new Float32Array(cap * 4), 4));
      const mesh = new THREE.InstancedMesh(geo, mat, cap);
      mesh.name = `Parked_${kind}_${lod}`;
      mesh.count = 0;
      mesh.frustumCulled = false;
      mesh.castShadow = lod === 'near';
      mesh.receiveShadow = true;
      return mesh;
    };
    const mat = moto ? createMotoMaterial() : createLoftedCarMaterial(SPECS[kind]);
    const near = mk(moto ? buildMotoGeometry(true) : buildCarGeometry(SPECS[kind], true), mat, 1024, 'near');
    const far = mk(moto ? buildMotoGeometry(false) : buildCarProxyGeometry(SPECS[kind]), mat, 4096, 'far');
    group.add(near, far);
    return { near, far };
  });
  group.add(shadowMesh);

  let lastX = Infinity, lastZ = Infinity;
  function update(pos) {
    if (Math.abs(pos.x - lastX) < MOVE && Math.abs(pos.z - lastZ) < MOVE) return;
    lastX = pos.x; lastZ = pos.z;
    for (const mm of meshes) { mm.near.count = 0; mm.far.count = 0; }
    shadowMesh.count = 0;
    const c0x = Math.floor((pos.x - FAR) / CELL), c1x = Math.floor((pos.x + FAR) / CELL);
    const c0z = Math.floor((pos.z - FAR) / CELL), c1z = Math.floor((pos.z + FAR) / CELL);
    for (let cx = c0x; cx <= c1x; cx++) {
      for (let cz = c0z; cz <= c1z; cz++) {
        const list = grid.get(cx * 100000 + cz);
        if (!list) continue;
        for (const j of list) {
          const dx = mats[j * 16 + 12] - pos.x, dz = mats[j * 16 + 14] - pos.z;
          const d2 = dx * dx + dz * dz;
          if (d2 > FAR * FAR) continue;
          const mesh = d2 < NEAR * NEAR ? meshes[kinds[j]].near : meshes[kinds[j]].far;
          if (mesh.count >= mesh.instanceMatrix.count) continue;
          const s = mesh.count++;
          mesh.instanceMatrix.array.set(mats.subarray(j * 16, j * 16 + 16), s * 16);
          mesh.geometry.attributes.paintColor.array.set(paints.subarray(j * 3, j * 3 + 3), s * 3);
          if (d2 < SHADOW * SHADOW && shadowMesh.count < shadowMesh.instanceMatrix.count) {
            shadowMesh.instanceMatrix.array.set(shadowMats.subarray(j * 16, j * 16 + 16), shadowMesh.count * 16);
            shadowMesh.count++;
          }
        }
      }
    }
    for (const mm of meshes) {
      for (const mesh of [mm.near, mm.far]) {
        mesh.instanceMatrix.clearUpdateRanges();
        mesh.instanceMatrix.addUpdateRange(0, mesh.count * 16);
        mesh.instanceMatrix.needsUpdate = true;
        const pa = mesh.geometry.attributes.paintColor;
        pa.clearUpdateRanges();
        pa.addUpdateRange(0, mesh.count * 3);
        pa.needsUpdate = true;
      }
    }
    shadowMesh.instanceMatrix.clearUpdateRanges();
    shadowMesh.instanceMatrix.addUpdateRange(0, shadowMesh.count * 16);
    shadowMesh.instanceMatrix.needsUpdate = true;
  }

  console.info(`[parked] ${stats.kept} of ${stats.data} parked vehicles (${stats.shifted} moved off the game's sidewalks, ` +
    `${stats.droppedSidewalk} with no room off them, ${stats.onPavement} motorbikes on the pavement, ${stats.droppedLane} in a moving lane, ${stats.droppedJunction} in a junction)`);
  return { group, colliders, update, stats, meshes };
}

// Is the vehicle's footprint (slightly inset) clear of every raised block (sidewalk, island, plaza)?
function clearOfSidewalk(x, z, cs, sn, L, hw) {
  const a = hw - 0.12, b = L / 2 - 0.15;
  for (const [u, w] of [[a, b], [-a, b], [a, -b], [-a, -b], [a, 0], [-a, 0], [0, 0]]) {
    // car frame (u along +x, w along +z) -> world
    if (blockAt(x + u * cs + w * sn, z - u * sn + w * cs)) return false;
  }
  return true;
}

// Is the footprint wholly on one raised block?
function onOneBlock(x, z, cs, sn, L, hw) {
  let first = null;
  for (const [u, w] of [[hw, L / 2], [-hw, L / 2], [hw, -L / 2], [-hw, -L / 2], [0, 0]]) {
    const b = blockAt(x + u * cs + w * sn, z - u * sn + w * cs);
    if (!b || (first && b !== first)) return false;
    first = b;
  }
  return true;
}

// The game's junctions (road graph nodes where three or more streets meet), as discs over their box and the widest
// street's half width: where the game's streets meet is no place for a parked car, even where the real ones don't
function junctionIndex(network) {
  if (!network || !network.edges) return null;
  const nb = new Map();
  const link = (a, b, half) => {
    if (!a || !b) return;
    let e = nb.get(a);
    if (!e) nb.set(a, (e = { set: new Set(), half: 0 }));
    e.set.add(b);
    e.half = Math.max(e.half, half || 0);
  };
  for (const e of network.edges) { link(e.from, e.to, e.half); link(e.to, e.from, e.half); }
  const cells = new Map();
  for (const [node, e] of nb) {
    if (e.set.size < 3 || !Number.isFinite(node.x)) continue;
    const r = Math.max(node.hx || 0, node.hz || 0, e.half) + 1.5;
    const j = { x: node.x, z: node.z, r };
    for (let ix = Math.floor((node.x - r) / 32); ix <= Math.floor((node.x + r) / 32); ix++) {
      for (let iz = Math.floor((node.z - r) / 32); iz <= Math.floor((node.z + r) / 32); iz++) {
        const k = ix * 100000 + iz;
        let list = cells.get(k);
        if (!list) cells.set(k, (list = []));
        list.push(j);
      }
    }
  }
  return cells;
}

function inJunction(cells, x, z) {
  const list = cells.get(Math.floor(x / 32) * 100000 + Math.floor(z / 32));
  return !!list && list.some((j) => Math.hypot(x - j.x, z - j.z) < j.r);
}

// Lane centrelines of the road graph (traffic.js / road-network.js edges), hashed into 32 m cells
function laneIndex(network) {
  if (!network || !network.edges) return null;
  const cells = new Map();
  for (const e of network.edges) {
    for (const o of e.lanes || []) {
      const ax = e.x0 + e.rx * o, az = e.z0 + e.rz * o;
      const seg = { ax, az, dx: e.dx, dz: e.dz, span: e.span };
      const bx = ax + e.dx * e.span, bz = az + e.dz * e.span;
      for (let ix = Math.floor(Math.min(ax, bx) / 32) - 1; ix <= Math.floor(Math.max(ax, bx) / 32) + 1; ix++) {
        for (let iz = Math.floor(Math.min(az, bz) / 32) - 1; iz <= Math.floor(Math.max(az, bz) / 32) + 1; iz++) {
          const k = ix * 100000 + iz;
          let list = cells.get(k);
          if (!list) cells.set(k, (list = []));
          list.push(seg);
        }
      }
    }
  }
  return cells;
}

// Does the vehicle overlap the swept path (centreline +/- 0.95 m) of a moving lane?
const LANE_HALF = 0.85; // the traffic's cars are 0.86-0.92 m half wide: at most a few cm of mirror overlap
function inLane(cells, x, z, cs, sn, L, hw) {
  const list = cells.get(Math.floor(x / 32) * 100000 + Math.floor(z / 32));
  if (!list) return false;
  const corners = [[hw, L / 2], [-hw, L / 2], [hw, -L / 2], [-hw, -L / 2]].map(([u, w]) => [x + u * cs + w * sn, z - u * sn + w * cs]);
  for (const s of list) {
    let lo = Infinity, hi = -Infinity, inSpan = false;
    for (const [px, pz] of corners) {
      const rx = px - s.ax, rz = pz - s.az;
      const along = rx * s.dx + rz * s.dz;
      if (along > 0.5 && along < s.span - 0.5) inSpan = true;
      const lat = rx * -s.dz + rz * s.dx;
      lo = Math.min(lo, lat); hi = Math.max(hi, lat);
    }
    if (inSpan && lo < LANE_HALF && hi > -LANE_HALF) return true;
  }
  return false;
}

export { KINDS as PARKED_KINDS, SPECS as PARKED_SPECS, CAR_PARTS };
